	public void assignMetric( AssignMetricToAlertCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignMetric(command.getAlertId(), command.getAssignment());

	}

